using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Positional;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.OrbitalAndPositional;
public sealed class AstronomyPositionValueValidationRuleTests { [Fact] public void Runtime_kind_matches_hierarchy_variant() => Assert.Empty(new AstronomyPositionValueValidationRule().Validate(OrbitalPositionalValidationFixture.AngularPayload(), OrbitalPositionalValidationFixture.Context())); [Fact] public void Cartesian_value_rejected_for_horizontal_context() { var position = OrbitalPositionalValidationFixture.CartesianPayload().Position with { ReferenceContext = OrbitalPositionalValidationFixture.SpatialContext(AstronomyCoordinateSystem.Horizontal, AstronomyReferenceOrigin.Topocentric) }; var payload = new Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional.AstronomySpatialPositionPayload(new("typed.positional.spatial-position.v1"), position); Assert.Contains(new AstronomyPositionValueValidationRule().Validate(payload, OrbitalPositionalValidationFixture.Context()), i => i.Code == AstronomyPositionalValidationCodes.PositionReferenceMismatch); } }
